const DOC_INDEX = new Map<string, ScreenDoc>();
for (const mod of MODULES) {
  for (const s of mod.screens) {
    DOC_INDEX.set(s.code, s);
  }
}

export function getScreenDoc(code: string): ScreenDoc | undefined {
  return DOC_INDEX.get(code);
}
